 6	int main(void)
 7	{
 8	    int passed = 0;
 9	    int failed = 0;
10	
11	    printf("=== RUNNING UI STATE & TOUCH LOGIC UNIT TESTS ===\n");
12	
13	    /* Test 1: A1 - Khoi tao man hinh mac dinh la Main Screen (0) */
14	    UI_State_Init();
15	    if (UI_State_Get() == UI_SCREEN_MAIN) {
16	        printf("[PASS] A1: UI_State_Init sets UI_SCREEN_MAIN (value 0)\n");
17	        passed++;
18	    } else {
19	        printf("[FAIL] A1: Expected UI_SCREEN_MAIN, got %d\n", UI_State_Get());
20	        failed++;
21	    }
22	
23	    /* Test 2: A2 - Cham vao giua nut (400, 425) phai nhan dien trung nut (1) */
24	    if (UI_State_CheckTouch(400, 425) == 1) {
25	        printf("[PASS] A2: UI_State_CheckTouch(400, 425) returned 1 (HIT)\n");
26	        passed++;
27	    } else {
28	        printf("[FAIL] A2: Touch at (400, 425) not detected\n");
29	        failed++;
30	    }
31	
32	    /* Test 3: A3 - Cham ngoai vung nut (50, 50) phai khong nhan dien (0) */
33	    if (UI_State_CheckTouch(50, 50) == 0) {
34	        printf("[PASS] A3: UI_State_CheckTouch(50, 50) returned 0 (MISS)\n");
35	        passed++;
36	    } else {
37	        printf("[FAIL] A3: Touch outside button (50, 50) falsely detected\n");
38	        failed++;
39	    }
40	
41	    /* Test 4: A4 - Chuyen trang thai tu Main sang Details (1) */
42	    UI_State_Init();
43	    if (UI_State_Toggle() == UI_SCREEN_DETAILS) {
44	        printf("[PASS] A4: UI_State_Toggle transitioned from MAIN to DETAILS (1)\n");
45	        passed++;
46	    } else {
47	        printf("[FAIL] A4: UI_State_Toggle did not transition to DETAILS\n");
48	        failed++;
49	    }
50	
51	    /* Test 5: A5 - Chuyen trang thai tu Details quay lai Main (0) */
52	    if (UI_State_Toggle() == UI_SCREEN_MAIN) {
53	        printf("[PASS] A5: UI_State_Toggle transitioned from DETAILS back to MAIN (0)\n");
54	        passed++;
55	    } else {
56	        printf("[FAIL] A5: UI_State_Toggle did not return to MAIN\n");
57	        failed++;
58	    }
59	
60	    /* Test 6: A6 - Toa do hoan doi truc (y=400, x=425) do huong cam ung FT6206 */
61	    if (UI_State_CheckTouch(425, 400) == 1) {
62	        printf("[PASS] A6: UI_State_CheckTouch with swapped axis returned 1\n");
63	        passed++;
64	    } else {
65	        printf("[FAIL] A6: Swapped axis touch not recognized\n");
66	        failed++;
67	    }
68	
69	    printf("\n=== SUMMARY: Total 6, Passed: %d, Failed: %d ===\n", passed, failed);
70	
71	    if (failed == 0) {
72	        return 0;
73	    }
74	    return 1;
75	}

