21	{
22	    if (current_ui_state == UI_SCREEN_MAIN) {
23	        current_ui_state = UI_SCREEN_DETAILS;
24	    } else {
25	        current_ui_state = UI_SCREEN_MAIN;
26	    }
27	    return current_ui_state;
