30	int UI_State_CheckTouch(uint16_t x, uint16_t y)
31	{
32	    int in_x = (x >= 150 && x <= 650);
33	    int in_y = ((y >= 380 && y <= 460) || (y >= 20 && y <= 100));
34	    int in_swap = (y >= 150 && y <= 650) && ((x >= 380 && x <= 460) || (x >= 20 && x <= 100));
35	
36	    if ((in_x && in_y) || in_swap) {
37	        return 1;
38	    }
39	    return 0;
40	}

