#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include "../firmware/ui_state.c"

int main(void)
{
    int passed = 0;
    int failed = 0;

    printf("=== RUNNING UI STATE & TOUCH LOGIC UNIT TESTS ===\n");

    /* Test 1: A1 - Khoi tao man hinh mac dinh la Main Screen (0) */
    UI_State_Init();
    int r1 = (UI_State_Get() == UI_SCREEN_MAIN);
    if (r1) {
        printf("{\"ma\": \"A1\", \"dat\": true, \"gia_tri\": %d, \"mo_ta\": \"UI_State_Init sets UI_SCREEN_MAIN\"}\n", UI_State_Get());
        passed++;
    } else {
        printf("{\"ma\": \"A1\", \"dat\": false, \"gia_tri\": %d, \"mo_ta\": \"UI_State_Init sets UI_SCREEN_MAIN\"}\n", UI_State_Get());
        failed++;
    }

    /* Test 2: A2 - Cham vao giua nut (400, 425) phai nhan dien trung nut (1) */
    int r2 = (UI_State_CheckTouch(400, 425) == 1);
    if (r2) {
        printf("{\"ma\": \"A2\", \"dat\": true, \"gia_tri\": 1, \"mo_ta\": \"Touch at (400, 425) detected\"}\n");
        passed++;
    } else {
        printf("{\"ma\": \"A2\", \"dat\": false, \"gia_tri\": 0, \"mo_ta\": \"Touch at (400, 425) not detected\"}\n");
        failed++;
    }

    /* Test 3: A3 - Cham ngoai vung nut (50, 50) phai khong nhan dien (0) */
    int r3 = (UI_State_CheckTouch(50, 50) == 0);
    if (r3) {
        printf("{\"ma\": \"A3\", \"dat\": true, \"gia_tri\": 0, \"mo_ta\": \"Touch outside (50, 50) rejected\"}\n");
        passed++;
    } else {
        printf("{\"ma\": \"A3\", \"dat\": false, \"gia_tri\": 1, \"mo_ta\": \"Touch outside (50, 50) falsely detected\"}\n");
        failed++;
    }

    /* Test 4: A4 - Chuyen trang thai tu Main sang Details (1) */
    UI_State_Init();
    int r4 = (UI_State_Toggle() == UI_SCREEN_DETAILS);
    if (r4) {
        printf("{\"ma\": \"A4\", \"dat\": true, \"gia_tri\": 1, \"mo_ta\": \"Toggle MAIN to DETAILS\"}\n");
        passed++;
    } else {
        printf("{\"ma\": \"A4\", \"dat\": false, \"gia_tri\": %d, \"mo_ta\": \"Toggle MAIN to DETAILS failed\"}\n", UI_State_Get());
        failed++;
    }

    /* Test 5: A5 - Chuyen trang thai tu Details quay lai Main (0) */
    int r5 = (UI_State_Toggle() == UI_SCREEN_MAIN);
    if (r5) {
        printf("{\"ma\": \"A5\", \"dat\": true, \"gia_tri\": 0, \"mo_ta\": \"Toggle DETAILS to MAIN\"}\n");
        passed++;
    } else {
        printf("{\"ma\": \"A5\", \"dat\": false, \"gia_tri\": %d, \"mo_ta\": \"Toggle DETAILS to MAIN failed\"}\n", UI_State_Get());
        failed++;
    }

    /* Test 6: A6 - Toa do hoan doi truc (y=400, x=425) do huong cam ung FT6206 */
    int r6 = (UI_State_CheckTouch(425, 400) == 1);
    if (r6) {
        printf("{\"ma\": \"A6\", \"dat\": true, \"gia_tri\": 1, \"mo_ta\": \"Swapped axis touch detected\"}\n");
